using KitWright.Editor.Tools.Scripting;
using UnityEngine;
using UnityEditor;
using UnityEditor.SceneManagement;
using System.Text;

public class CommandScript : IKitWrightCommand
{
    public void Execute(ExecutionContext ctx)
    {
        var sb = new StringBuilder();
        if (EditorApplication.isPlaying)
        {
            ctx.ReturnValue = "playing abort";
            return;
        }

        var scene = EditorSceneManager.OpenScene("Assets/Project/GameLobby.unity");
        sb.AppendLine("opened " + scene.path);

        Transform FindDeep(string name)
        {
            foreach (var t in Resources.FindObjectsOfTypeAll<Transform>())
            {
                if (EditorUtility.IsPersistent(t.gameObject)) continue;
                if (t.name == name) return t;
            }
            return null;
        }

        void SetGo(GameObject go, bool active, string label)
        {
            if (go == null) { sb.AppendLine("MISSING " + label); return; }
            ctx.RegisterObjectModification(go);
            go.SetActive(active);
            sb.AppendLine((active ? "ON " : "OFF ") + label);
        }

        // Roots to hide
        SetGo(FindDeep("Canvas_Lobby_Legacy")?.gameObject, false, "Canvas_Lobby_Legacy");
        SetGo(FindDeep("UI_Toolkit_Lobby_Root")?.gameObject, false, "UI_Toolkit_Lobby_Root");
        SetGo(FindDeep("Canvas_Background")?.gameObject, false, "Canvas_Background");

        var yellow = FindDeep("Yellow_HUD_Root");
        SetGo(yellow?.gameObject, true, "Yellow_HUD_Root");

        if (yellow != null)
        {
            // Ensure ancestors active
            var p = yellow.parent;
            while (p != null)
            {
                if (!p.gameObject.activeSelf)
                {
                    ctx.RegisterObjectModification(p.gameObject);
                    p.gameObject.SetActive(true);
                    sb.AppendLine("parent ON " + p.name);
                }
                p = p.parent;
            }

            // Only disable Reach Multiplayer Content siblings that fight Yellow HUD
            var content = yellow.parent;
            if (content != null)
            {
                for (int i = 0; i < content.childCount; i++)
                {
                    var c = content.GetChild(i);
                    if (c == yellow) continue;
                    // Keep Customization available but off by default
                    if (c.name == "Customization_UI_Root")
                    {
                        SetGo(c.gameObject, false, "Customization_UI_Root");
                        continue;
                    }
                    SetGo(c.gameObject, false, "Multiplayer/Content/" + c.name);
                }
            }
        }

        SetGo(FindDeep("LobbyCharacterStage")?.gameObject, true, "LobbyCharacterStage");

        var bridge = Object.FindObjectOfType<Michsky.UI.Reach.ReachLobbyBridge>(true);
        if (bridge != null)
        {
            ctx.RegisterObjectModification(bridge);
            var so = new SerializedObject(bridge);
            var use3d = so.FindProperty("use3DCharacterStage");
            if (use3d != null) use3d.boolValue = true;
            var stageProp = so.FindProperty("lobby3DStage");
            if (stageProp != null && stageProp.objectReferenceValue == null)
            {
                var stageGo = FindDeep("LobbyCharacterStage");
                if (stageGo != null) stageProp.objectReferenceValue = stageGo.gameObject;
            }
            so.ApplyModifiedPropertiesWithoutUndo();
            sb.AppendLine("bridge use3D=true");

            // Hide 2D placeholder if assigned
            var ph = so.FindProperty("placeholderModel2D");
            if (ph != null && ph.objectReferenceValue is GameObject pgo)
            {
                ctx.RegisterObjectModification(pgo);
                pgo.SetActive(false);
                sb.AppendLine("hid 2d placeholder");
            }
        }
        else sb.AppendLine("NO ReachLobbyBridge");

        // Ensure Event System active under Reach canvas
        var es = FindDeep("Event System");
        SetGo(es?.gameObject, true, "Event System");

        EditorSceneManager.MarkSceneDirty(scene);
        EditorSceneManager.SaveScene(scene);
        sb.AppendLine("saved yellowActive=" + (yellow != null && yellow.gameObject.activeSelf));
        ctx.ReturnValue = sb.ToString();
    }
}
